CREATE TABLE dbo.SessionState
(
    SessionId VARCHAR(50) NOT NULL,
    Payload NVARCHAR(MAX) NOT NULL,
    CONSTRAINT PK_SessionState PRIMARY KEY NONCLUSTERED HASH (SessionId)
        WITH (BUCKET_COUNT = 16384)
) WITH (MEMORY_OPTIMIZED = ON, DURABILITY = SCHEMA_ONLY);

CREATE TABLE dbo.ColumnKey
(
    Id INT NOT NULL PRIMARY KEY NONCLUSTERED HASH WITH (BUCKET_COUNT = 1024)
) WITH (MEMORY_OPTIMIZED = ON);

CREATE TABLE dbo.InlineHash
(
    Id INT NOT NULL,
    INDEX IX_Id NONCLUSTERED HASH (Id) WITH (BUCKET_COUNT = 2048)
) WITH (MEMORY_OPTIMIZED = ON);

CREATE TABLE dbo.ImplicitNonclustered
(
    Id INT NOT NULL,
    INDEX IX_Id HASH (Id) WITH (BUCKET_COUNT = 4096)
) WITH (MEMORY_OPTIMIZED = ON);

CREATE TABLE dbo.ColumnIndex
(
    Id INT NOT NULL INDEX IX_Id NONCLUSTERED HASH WITH (BUCKET_COUNT = 8192)
) WITH (MEMORY_OPTIMIZED = ON);

CREATE TABLE dbo.CompositeKey
(
    Id INT NOT NULL,
    Category INT NOT NULL,
    CONSTRAINT UQ_Id_Category UNIQUE NONCLUSTERED HASH (Id, Category)
        WITH (BUCKET_COUNT = 65536)
) WITH (MEMORY_OPTIMIZED = ON);

CREATE TABLE dbo.RangeIndex
(
    Id INT NOT NULL PRIMARY KEY NONCLUSTERED,
    INDEX IX_Id NONCLUSTERED (Id)
) WITH (MEMORY_OPTIMIZED = ON);
